parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "relevancia_recuperacion": {
      "type": "integer",
      "description": "METRICA DE RECUPERACION. Entero de 1 a 5. Mide si el contexto que recibio el agente contenia lo necesario para responder, con independencia de como respondio. 5 = el contexto contiene toda la informacion necesaria; 1 = el contexto es irrelevante o esta vacio."
    },
    "fidelidad_a_fuentes": {
      "type": "integer",
      "description": "METRICA DE GENERACION. Entero de 1 a 5. Mide si todo lo afirmado en la respuesta esta respaldado por el contexto recibido. 5 = cada afirmacion es rastreable al contexto; 1 = afirma cosas que el contexto no dice."
    },
    "exactitud_citas": {
      "type": "string",
      "enum": [
        "correcta",
        "ausente",
        "incorrecta",
        "no_aplica"
      ],
      "description": "correcta = cita una seccion y el dato efectivamente proviene de ella; ausente = afirma sobre politicas sin citar; incorrecta = cita una seccion que no corresponde al dato; no_aplica = la respuesta no versa sobre politicas."
    },
    "exactitud_factual": {
      "type": "integer",
      "description": "PUNTAJE GLOBAL. Entero de 1 a 5. 5 = todo dato afirmado aparece literal en el contexto; 1 = inventa informacion sustantiva."
    },
    "estado_veredicto": {
      "type": "string",
      "enum": [
        "ACEPTADO",
        "CORREGIR",
        "RECHAZADO"
      ]
    },
    "categoria_error": {
      "type": "string",
      "enum": [
        "ninguno",
        "dato_inventado",
        "dato_contradictorio",
        "fuera_de_alcance",
        "cobertura_incompleta",
        "tono_inadecuado",
        "cita_incorrecta",
        "fallo_de_recuperacion"
      ]
    },
    "justificacion": {
      "type": "string",
      "description": "Maximo 200 caracteres. Cita el dato concreto que motiva el veredicto."
    }
  },
  "required": [
    "relevancia_recuperacion",
    "fidelidad_a_fuentes",
    "exactitud_citas",
    "exactitud_factual",
    "estado_veredicto",
    "categoria_error",
    "justificacion"
  ]
}

parameters.jsCode:
// Blindaje del veredicto: el Switch del Manager necesita un valor de una
// lista cerrada. Si el parser fallara, un veredicto invalido romperia el
// ruteo, asi que se degrada a RECHAZADO (el lado seguro).
const VALIDOS = ['ACEPTADO', 'CORREGIR', 'RECHAZADO'];
const CITAS = ['correcta', 'ausente', 'incorrecta', 'no_aplica'];
const src = $input.first().json.output ?? $input.first().json;

const nota = (v) => {
  const n = parseInt(v, 10);
  return (Number.isInteger(n) && n >= 1 && n <= 5) ? n : 1;
};

let veredicto = (src.estado_veredicto || '').toString().toUpperCase().trim();
if (!VALIDOS.includes(veredicto)) veredicto = 'RECHAZADO';

let citas = (src.exactitud_citas || 'no_aplica').toString().toLowerCase().trim();
if (!CITAS.includes(citas)) citas = 'no_aplica';

return [{ json: {
  relevancia_recuperacion: nota(src.relevancia_recuperacion),
  fidelidad_a_fuentes:     nota(src.fidelidad_a_fuentes),
  exactitud_citas:         citas,
  exactitud_factual:       nota(src.exactitud_factual),
  estado_veredicto:        veredicto,
  categoria_error:         (src.categoria_error || 'ninguno').toString(),
  justificacion:           (src.justificacion || '').toString().slice(0, 200)
}}];
